            if nums[l] % 2 or nums[l] > threshold: continue
            r = l
            while r + 1 < n and nums[r + 1] <= threshold and nums[r + 1] % 2 != nums[r] % 2:
                r += 1
            ans = max(ans, r - l + 1)
